"use strict";(self.webpackChunkturboquant_lectures=self.webpackChunkturboquant_lectures||[]).push([["6061"],{9571(n){n.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/google-turbo-quant/docs/roadmap","label":"\u{1F5FA}\uFE0F Roadmap & Syllabus","docId":"roadmap","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_0_vector_quantization_background","label":"B\xe0i 0: N\u1EC1n t\u1EA3ng Vector Quantization","docId":"lesson_0_vector_quantization_background","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_1_kv_cache_problem","label":"B\xe0i 1: B\xe0i to\xe1n KV Cache & Data-Oblivious","docId":"lesson_1_kv_cache_problem","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_2_random_rotation_beta","label":"B\xe0i 2: Random Rotation & Ph\xe2n ph\u1ED1i Beta","docId":"lesson_2_random_rotation_beta","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_3_mse_scalar_quantizer","label":"B\xe0i 3: MSE Scalar Quantizer t\u1ED1i \u01B0u","docId":"lesson_3_mse_scalar_quantizer","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_4_inner_product_qjl","label":"B\xe0i 4: Inner Product & QJL Unbiased","docId":"lesson_4_inner_product_qjl","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_5_vllm_integration","label":"B\xe0i 5: T\xedch h\u1EE3p TurboQuant v\xe0o vLLM","docId":"lesson_5_vllm_integration","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_6_lower_bound_optimality","label":"B\xe0i 6: C\u1EADn d\u01B0\u1EDBi & T\xednh t\u1ED1i \u01B0u (~2.7)","docId":"lesson_6_lower_bound_optimality","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_7_nearest_neighbor_search","label":"B\xe0i 7: Nearest Neighbor Search & Vector DB","docId":"lesson_7_nearest_neighbor_search","unlisted":false},{"type":"link","href":"/google-turbo-quant/docs/lesson_8_toy_turboquant","label":"B\xe0i 8: Th\u1EF1c h\xe0nh \u2014 Toy TurboQuant","docId":"lesson_8_toy_turboquant","unlisted":false}]},"docs":{"lesson_0_vector_quantization_background":{"id":"lesson_0_vector_quantization_background","title":"B\xe0i 0: N\u1EC1n t\u1EA3ng Vector Quantization & Rate-Distortion","description":"Tr\u01B0\u1EDBc khi m\u1ED5 x\u1EBB TurboQuant, ch\xfang ta c\u1EA7n m\u1ED9t n\u1EC1n t\u1EA3ng v\u1EEFng ch\u1EAFc v\u1EC1 l\u01B0\u1EE3ng h\xf3a (quantization) d\u01B0\u1EDBi g\xf3c nh\xecn c\u1EE7a l\xfd thuy\u1EBFt m\xe3 h\xf3a ngu\u1ED3n (source coding) c\u1EE7a Shannon. B\xe0i n\xe0y tr\u1EA3 l\u1EDDi ba c\xe2u h\u1ECFi: (1) M\xe9o (distortion) l\xe0 g\xec v\xe0 \u0111o th\u1EBF n\xe0o? (2) Gi\u1EDBi h\u1EA1n t\u1ED1t nh\u1EA5t c\xf3 th\u1EC3 \u0111\u1EA1t \u0111\u01B0\u1EE3c (rate-distortion bound) l\xe0 bao nhi\xeau? (3) V\xec sao l\u01B0\u1EE3ng h\xf3a vector v\u1EC1 nguy\xean t\u1EAFc lu\xf4n t\u1ED1t h\u01A1n l\u01B0\u1EE3ng h\xf3a t\u1EEBng s\u1ED1 (scalar)?","sidebar":"tutorialSidebar"},"lesson_1_kv_cache_problem":{"id":"lesson_1_kv_cache_problem","title":"B\xe0i 1: B\xe0i to\xe1n n\xe9n KV Cache & y\xeau c\u1EA7u Data-Oblivious","description":"B\xe0i 0 cho ta n\u1EC1n t\u1EA3ng l\xfd thuy\u1EBFt. B\xe0i n\xe0y gi\u1EA3i th\xedch v\xec sao b\xe0i to\xe1n m\xe0 TurboQuant gi\u1EA3i l\u1EA1i quan tr\u1ECDng \u0111\u1EBFn v\u1EADy trong th\u1EF1c t\u1EBF LLM serving, v\xe0 \u0111\xe2u l\xe0 r\xe0ng bu\u1ED9c kh\u1EAFc nghi\u1EC7t (online, data-oblivious) khi\u1EBFn h\u1EA7u h\u1EBFt ph\u01B0\u01A1ng ph\xe1p VQ truy\u1EC1n th\u1ED1ng th\u1EA5t b\u1EA1i.","sidebar":"tutorialSidebar"},"lesson_2_random_rotation_beta":{"id":"lesson_2_random_rotation_beta","title":"B\xe0i 2: Tr\u1EE5 c\u1ED9t 1 \u2014 Random Rotation & Ph\xe2n ph\u1ED1i Beta","description":"\u0110\xe2y l\xe0 tr\xe1i tim c\u1EE7a TurboQuant. To\xe0n b\u1ED9 \\"ph\xe9p m\xe0u\\" n\u1EB1m \u1EDF m\u1ED9t quan s\xe1t to\xe1n h\u1ECDc tuy\u1EC7t \u0111\u1EB9p: n\u1EBFu b\u1EA1n xoay ng\u1EABu nhi\xean m\u1ED9t vector \u1EDF chi\u1EC1u cao, m\u1ECDi t\u1ECDa \u0111\u1ED9 c\u1EE7a n\xf3 s\u1EBD tu\xe2n theo c\xf9ng m\u1ED9t ph\xe2n ph\u1ED1i \u0111\xe3 bi\u1EBFt, v\xe0 g\u1EA7n nh\u01B0 \u0111\u1ED9c l\u1EADp v\u1EDBi nhau. Quan s\xe1t n\xe0y bi\u1EBFn b\xe0i to\xe1n vector quantization kh\xf3 th\xe0nh $d$ b\xe0i to\xe1n scalar quantization d\u1EC5.","sidebar":"tutorialSidebar"},"lesson_3_mse_scalar_quantizer":{"id":"lesson_3_mse_scalar_quantizer","title":"B\xe0i 3: Tr\u1EE5 c\u1ED9t 2 \u2014 MSE Scalar Quantizer t\u1ED1i \u01B0u","description":"B\xe0i 2 \u0111\xe3 bi\u1EBFn vector $x$ th\xe0nh $\\\\tilde x = Rx$ v\u1EDBi c\xe1c t\u1ECDa \u0111\u1ED9 i.i.d. x\u1EA5p x\u1EC9 Gauss. Gi\u1EDD nhi\u1EC7m v\u1EE5 ch\u1EC9 c\xf2n l\xe0: thi\u1EBFt k\u1EBF m\u1ED9t b\u1ED9 l\u01B0\u1EE3ng h\xf3a v\xf4 h\u01B0\u1EDBng $q^\\\\star$ t\u1ED1i \u01B0u cho ph\xe2n ph\u1ED1i \u0111\xf3, r\u1ED3i \xe1p cho m\u1ECDi t\u1ECDa \u0111\u1ED9. B\xe0i n\xe0y tr\xecnh b\xe0y c\xe1ch thi\u1EBFt k\u1EBF v\xe0 \u2014 quan tr\u1ECDng nh\u1EA5t \u2014 t\xednh ch\xednh x\xe1c m\xe9o c\u1EE7a n\xf3, t\u1EEB \u0111\xf3 suy ra c\xf4ng th\u1EE9c $D(b)$ then ch\u1ED1t.","sidebar":"tutorialSidebar"},"lesson_4_inner_product_qjl":{"id":"lesson_4_inner_product_qjl","title":"B\xe0i 4: Tr\u1EE5 c\u1ED9t 3 \u2014 Inner Product Distortion & QJL","description":"Hai tr\u1EE5 c\u1ED9t \u0111\u1EA7u (random rotation + MSE quantizer) \u0111\xe3 cho ta m\u1ED9t b\u1ED9 n\xe9n t\u1ED1i \u01B0u MSE. Nh\u01B0ng nh\u01B0 \u0111\xe3 c\u1EA3nh b\xe1o \u1EDF B\xe0i 0, t\u1ED1i \u01B0u MSE ch\u01B0a \u0111\u1EE7 cho Attention: th\u1EE9 Attention c\u1EA7n l\xe0 t\xedch v\xf4 h\u01B0\u1EDBng $\\\\langle q, k\\\\rangle$, v\xe0 b\u1ED9 l\u01B0\u1EE3ng h\xf3a MSE l\u1EA1i g\xe2y thi\xean l\u1EC7ch (bias) tr\xean \u0111\u1EA1i l\u01B0\u1EE3ng n\xe0y. B\xe0i n\xe0y gi\u1EA3i th\xedch bias \u0111\xf3 t\u1EEB \u0111\xe2u ra v\xe0 c\xe1ch TurboQuant kh\u1EED n\xf3 b\u1EB1ng Quantized Johnson\u2013Lindenstrauss (QJL).","sidebar":"tutorialSidebar"},"lesson_5_vllm_integration":{"id":"lesson_5_vllm_integration","title":"B\xe0i 5: T\xedch h\u1EE3p TurboQuant v\xe0o vLLM KV Cache","description":"\u0110\xe2y l\xe0 b\xe0i \\"k\u1EF9 thu\u1EADt h\u1EC7 th\u1ED1ng\\" tr\u1ECDng t\xe2m: ta l\u1EA5y thu\u1EADt to\xe1n TurboQuant (B\xe0i 2\u20134) v\xe0 \xe1nh x\u1EA1 n\xf3 v\xe0o ki\u1EBFn tr\xfac th\u1EF1c t\u1EBF c\u1EE7a vLLM \u0111\u1EC3 n\xe9n KV Cache l\xfac serving. M\u1EE5c ti\xeau l\xe0 ch\u1EC9 r\xf5 ch\xednh x\xe1c TurboQuant ph\u1EA3i \\"c\u1EAFm\\" v\xe0o \u0111\xe2u trong \u0111\u01B0\u1EDDng \u0111i c\u1EE7a d\u1EEF li\u1EC7u, nh\u1EEFng kernel n\xe0o c\u1EA7n vi\u1EBFt, v\xe0 so s\xe1nh v\u1EDBi c\u01A1 ch\u1EBF FP8 KV Cache m\xe0 vLLM \u0111\xe3 c\xf3 s\u1EB5n.","sidebar":"tutorialSidebar"},"lesson_6_lower_bound_optimality":{"id":"lesson_6_lower_bound_optimality","title":"B\xe0i 6: C\u1EADn d\u01B0\u1EDBi l\xfd thuy\u1EBFt & T\xednh t\u1ED1i \u01B0u (~2.7)","description":"Tuy\xean b\u1ED1 m\u1EA1nh nh\u1EA5t c\u1EE7a TurboQuant l\xe0 \\"near-optimal distortion rate\\" \u2014 g\u1EA7n t\u1ED1i \u01B0u. Nh\u01B0ng \\"g\u1EA7n t\u1ED1i \u01B0u\\" so v\u1EDBi c\xe1i g\xec? B\xe0i n\xe0y l\xe0m r\xf5: paper ch\u1EE9ng minh m\u1ED9t c\u1EADn d\u01B0\u1EDBi (lower bound) th\xf4ng tin m\xe0 m\u1ECDi vector quantizer \u0111\u1EC1u ph\u1EA3i tu\xe2n theo, r\u1ED3i ch\u1EC9 ra TurboQuant ch\u1EC9 c\xe1ch c\u1EADn \u0111\xf3 \u0111\xfang m\u1ED9t h\u1EB1ng s\u1ED1 $\\\\approx 2.72$, \u0111\u1ED3ng \u0111\u1EC1u \u1EDF m\u1ECDi bit-width v\xe0 m\u1ECDi chi\u1EC1u.","sidebar":"tutorialSidebar"},"lesson_7_nearest_neighbor_search":{"id":"lesson_7_nearest_neighbor_search","title":"B\xe0i 7: \u1EE8ng d\u1EE5ng \u2014 Nearest Neighbor Search & Vector Database","description":"KV Cache kh\xf4ng ph\u1EA3i \u1EE9ng d\u1EE5ng duy nh\u1EA5t. V\xec TurboQuant t\u1ED1i \u01B0u c\u1EA3 inner product distortion, n\xf3 l\xe0 m\u1ED9t \u1EE9ng vi\xean xu\u1EA5t s\u1EAFc cho t\xecm ki\u1EBFm l\xe2n c\u1EADn g\u1EA7n nh\u1EA5t (Nearest Neighbor Search - NNS) v\xe0 vector database \u2014 n\u1EC1n t\u1EA3ng c\u1EE7a RAG, semantic search, h\u1EC7 th\u1ED1ng g\u1EE3i \xfd. B\xe0i n\xe0y ph\xe2n t\xedch v\xec sao TurboQuant v\u01B0\u1EE3t Product Quantization (PQ) \u1EDF \u0111\xfang nh\u1EEFng \u0111i\u1EC3m PQ y\u1EBFu nh\u1EA5t.","sidebar":"tutorialSidebar"},"lesson_8_toy_turboquant":{"id":"lesson_8_toy_turboquant","title":"B\xe0i 8: Th\u1EF1c h\xe0nh \u2014 T\u1EF1 x\xe2y d\u1EF1ng Toy TurboQuant","description":"L\xfd thuy\u1EBFt \u0111\xe3 \u0111\u1EE7. Gi\u1EDD ta t\u1EF1 code to\xe0n b\u1ED9 TurboQuant b\u1EB1ng Python & NumPy \u0111\u1EC3 ki\u1EC3m ch\u1EE9ng ba tuy\xean b\u1ED1 c\u1ED1t l\xf5i \u0111\xe3 h\u1ECDc: (1) random rotation di\u1EC7t outlier & b\u1EA3o to\xe0n h\xecnh h\u1ECDc, (2) m\xe9o MSE g\u1EA7n c\u1EADn t\u1ED1i \u01B0u v\u1EDBi h\u1EB1ng s\u1ED1 ~2.72, (3) QJL cho \u01B0\u1EDBc l\u01B0\u1EE3ng inner product kh\xf4ng thi\xean l\u1EC7ch. M\xe3 ngu\u1ED3n n\u1EB1m trong th\u01B0 m\u1EE5c toyquant/.","sidebar":"tutorialSidebar"},"roadmap":{"id":"roadmap","title":"TurboQuant Internals: Ph\xe2n t\xedch thu\u1EADt to\xe1n & T\xedch h\u1EE3p vLLM","description":"Ch\xe0o m\u1EEBng b\u1EA1n \u0111\u1EBFn v\u1EDBi chu\u1ED7i b\xe0i gi\u1EA3ng TurboQuant Internals. \u0110\xe2y l\xe0 t\xe0i li\u1EC7u ph\xe2n t\xedch chuy\xean s\xe2u (b\u1EB1ng ti\u1EBFng Vi\u1EC7t) v\u1EC1 thu\u1EADt to\xe1n TurboQuant \u2014 c\xf4ng tr\xecnh \\"TurboQuant2504.19874).","sidebar":"tutorialSidebar"}}}}')}}]);